window.ME_DATA = window.ME_DATA || {};
window.ME_DATA["y10-me"] = [
 {
  id:"l1", lesson:1, title:"International Ethics in the Context of Global Issues", unit:"Unit 1: Introduction to Global Ethics", art:"globe",
  dna:"Think of something you bought, ate or used today (e.g. your phone, your breakfast, your trainers). Write down which countries might have been involved in making it or bringing it to you. What does this tell you about how connected the world is?",
  dnaQs:["Name ONE thing you used or ate today.","Which countries might have been involved in making it or bringing it to you?","What does this tell you about how connected the world is?"],
  dnaHint:"A good answer names a specific item (for example, a phone designed in one country, assembled in another, using materials mined in a third), and concludes that our everyday choices connect us to people in many countries — so our actions can affect people we will never meet.",
  intentions:["Understand what is meant by international (global) ethics.","Explore why global issues require moral thinking beyond national borders.","Apply ethical principles to judge a global issue."],
  criteria:["I can explain what international ethics means.","I can explain why global issues need moral thinking that goes beyond one country.","I can apply an ethical principle to judge a real global issue."],
  concept:{key:"Global interactions", related:"Responsibility, Interdependence", soi:"In an interdependent world, individuals and nations share moral responsibilities that extend beyond their own borders.", context:"Globalisation and Sustainability — exploring how local actions connect to global consequences.", uae:"The UAE's vision of global partnership and tolerance, including the Document on Human Fraternity signed in Abu Dhabi in 2019; links to Individuals & Societies (globalisation)."},
  words:[["Ethics","The study of what is morally right and wrong, and how we ought to act."],["International ethics","Moral principles that guide how nations, organisations and people act toward others across the world."],["Globalisation","The process by which countries, economies and cultures become increasingly connected."],["Interdependence","A situation where people or countries rely on each other."],["Global citizen","A person who sees themselves as part of a world community and acts responsibly toward it."],["Universal value","A moral value recognised as important by people across many cultures, such as justice or human dignity."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion B — Investigating", steps:["Choose ONE global issue that crosses national borders (e.g. ocean plastic, food waste, air pollution, access to education).","Research it using at least two reliable sources (e.g. UN agencies, reputable news organisations).","Record: why no single country can solve this issue alone.","Note one ethical principle (e.g. fairness, responsibility, human dignity) that should guide how countries respond."], prompts:["The global issue I chose and my two sources","Why no single country can solve it alone","The ethical principle that should guide the response, and why"], success:"Good examples include ocean plastic (waste from one country travels across oceans), air pollution (it does not stop at borders) and global education gaps. Strong answers clearly explain the cross-border nature of the issue (e.g. currents carry plastic thousands of kilometres) and link it to a specific ethical principle, such as fairness or shared responsibility, rather than just describing the problem. For the top band, use two credible sources and justify why the chosen principle fits."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"A large company produces cheap clothes that are popular with teenagers worldwide. Reports suggest that some of the factories making the clothes pay very low wages and have unsafe working conditions. Shoppers in other countries say, 'It is not our problem — we only buy the clothes.'", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain whether the shoppers have any moral responsibility in this situation.","Use at least THREE words from the Word Bank (e.g. interdependence, global citizen, international ethics) accurately.","Conclude with one realistic action a responsible consumer could take."], model:"Although the shoppers are far away from the factories, international ethics suggests they do have some moral responsibility, because globalisation links their buying choices directly to the lives of workers in other countries. This interdependence means that demand for very cheap clothing can encourage companies to cut costs at the expense of workers' safety and fair pay. Being a global citizen does not mean shoppers must solve the problem alone, but it does mean they should not ignore it. A realistic action would be to research brands before buying and to choose companies that are open about how their workers are treated.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; the action is realistic and well-justified."]], starters:["Although the shoppers are far away, ___.","Globalisation links their choices to ___ because ___.","This interdependence means ___.","A responsible consumer could ___ because ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Global Citizen Pledge Campaign", steps:["In groups of 3–4, choose ONE global issue from your research.","Identify the main ethical principle at stake and explain who is affected and how.","Create a 'Global Citizen Pledge' of 3–4 realistic actions students in the UAE could take to respond to the issue.","Design a short campaign poster or digital slide to encourage your year group to sign the pledge.","Present your campaign in a 3-minute pitch. Use Word Bank vocabulary in your presentation."], rubric:[["1–2","Issue is described vaguely; pledge actions are unrealistic or missing."],["3–4","Issue is identified; ethical principle is named but not explained; actions are basic."],["5–6","Clear explanation of the issue and ethical principle; pledge actions are realistic and relevant."],["7–8","Insightful explanation of the issue and principle; pledge actions are practical, specific and convincingly justified."]]},
  game:{type:"sort", title:"Local or Global?", prompt:"Sort each issue: is it mainly a local issue, or a global issue that crosses borders?", bins:["Mainly a local issue","A global issue that crosses borders"], items:[["Litter in your school playground",0],["Plastic waste travelling across the oceans",1],["Climate change",1],["A broken streetlight in your community",0],["The spread of an infectious disease between countries",1],["Unsafe working conditions in factories that supply goods worldwide",1],["A noisy neighbour",0],["Children around the world without access to school",1]]},
  quiz:[["What is 'international ethics'?",["Moral principles that guide how nations, organisations and people act toward others across the world","The laws of one country only","A type of trade agreement"],0],["What does 'interdependence' mean?",["Being completely independent","A situation where people or countries rely on each other","A type of government"],1],["What is 'globalisation'?",["Countries closing their borders","Travelling on holiday","The process by which countries, economies and cultures become increasingly connected"],2],["Why do global issues need international ethics?",["Because they only affect one country","Because their causes and effects cross national borders","Because they are not serious"],1],["Which is an example of a universal value?",["Human dignity","A national football team","A school timetable"],0],["In the extract, why might the shoppers have some responsibility?",["Because they own the factory","Because they make the clothes themselves","Because their buying choices are linked to the lives of the workers"],2],["Which document promoting tolerance and coexistence was signed in Abu Dhabi in 2019?",["The Paris Agreement","The Document on Human Fraternity","The UN Charter"],1],["A global citizen is someone who…",["Only cares about their own country","Has travelled to many countries","Sees themselves as part of a world community and acts responsibly toward it"],2]],
  exit:"Write ONE way a choice you make in Dubai could affect someone in another country.",
  copy:{facts:["International ethics is about the moral principles that guide how nations, organisations and people treat others across the world.","Globalisation and interdependence mean our everyday choices can affect people we will never meet.","Universal values such as human dignity, justice and responsibility help guide responses to global issues."]},
  next:"Next lesson: we continue Unit 1 by exploring the UAE's international relations and its role in the world."
 },
 {
  id:"l2", lesson:2, title:"The UAE's International Relations", unit:"Unit 1: Introduction to Global Ethics", art:"community",
  dna:"Recap: in one sentence, explain what 'international ethics' means from last lesson. Now think: write down ONE way you have seen the UAE working with or helping other countries (e.g. in the news, at an event, or through aid).",
  dnaQs:["In one sentence, what does 'international ethics' mean?","Name ONE way you have seen the UAE working with or helping other countries."],
  dnaHint:"International ethics is about the moral principles that guide how nations and people act toward others across the world. For the UAE example, you could mention humanitarian aid after a disaster, hosting COP28 or Expo 2020 Dubai, or welcoming people from many nationalities to live and work here.",
  intentions:["Understand the key principles of the UAE's foreign policy and international relations.","Explore how the UAE builds partnerships through diplomacy, aid and cooperation.","Evaluate how the UAE's international relations reflect its national values."],
  criteria:["I can describe key principles of the UAE's international relations.","I can give examples of how the UAE works with other countries.","I can evaluate how these relations reflect UAE values such as tolerance and generosity."],
  concept:{key:"Global interactions", related:"Diplomacy, Cooperation", soi:"Nations build peaceful and productive relationships through diplomacy, cooperation and shared values.", context:"Fairness and Development — exploring how nations cooperate to promote peace and development.", uae:"The UAE joined the United Nations in 1971, served on the UN Security Council (2022–2023), hosted COP28 in Dubai in 2023, and is recognised as a major donor of foreign aid; links to Individuals & Societies (government and international relations)."},
  words:[["Diplomacy","Managing relationships between countries through discussion and negotiation."],["Foreign policy","A country's plan for how it deals with other countries."],["Foreign aid","Money, goods or services given by one country to help another."],["Alliance","A partnership between countries for shared benefit or protection."],["Sovereignty","A country's right to govern itself without outside interference."],["Mediation","Helping two sides in a dispute reach an agreement."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion A — Knowing and Understanding", steps:["Choose ONE example of the UAE's international relations (e.g. its UN membership, hosting COP28, humanitarian aid after a disaster, mediation between countries, or Expo 2020 Dubai).","Research it using at least two reliable sources (e.g. official UAE government websites, WAM news agency, UN websites).","Record: what happened, which countries or organisations were involved, and what the aim was.","Note which UAE value (e.g. tolerance, generosity, peace, cooperation) this example reflects."], prompts:["The example I chose and my two sources","What happened and who was involved","What the aim was","The UAE value it reflects, and why"], success:"Good examples include the UAE joining the UN in 1971, its term on the UN Security Council (2022–2023), hosting COP28 at Expo City Dubai in 2023, delivering humanitarian aid through organisations such as the Emirates Red Crescent, and helping mediate prisoner exchanges between countries. Strong answers give accurate details from reliable sources and clearly connect the example to a specific UAE value. For the top band, explain both the aim and the impact of the example."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"Since its founding in 1971, the UAE has followed a foreign policy based on dialogue, respect for other nations' sovereignty and peaceful solutions to disputes. Today it works with countries across the world on trade, humanitarian aid, climate action and tolerance.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain why a foreign policy based on dialogue and cooperation can benefit both the UAE and the wider world.","Use at least THREE words from the Word Bank (e.g. diplomacy, foreign aid, sovereignty) accurately.","Conclude with one reason why this approach is ethical, not only practical."], model:"A foreign policy based on dialogue and cooperation benefits both the UAE and the wider world because it builds trust and reduces the risk of conflict. Through diplomacy, the UAE can strengthen trade and partnerships, while respecting other nations' sovereignty helps relationships stay peaceful and fair. For example, by providing foreign aid after natural disasters, the UAE supports people in need while also building lasting friendships between countries. This approach is ethical, not only practical, because it reflects the values of generosity and respect for human dignity that are central to UAE identity.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; ethical reason is clear and well-justified."]], starters:["A foreign policy based on dialogue benefits ___ because ___.","Through diplomacy, the UAE can ___.","For example, by providing foreign aid, ___.","This approach is ethical because ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"UAE in the World Timeline", steps:["In groups of 3–4, create a timeline of 6–8 key moments in the UAE's international relations since 1971.","For each moment, write one sentence explaining what happened and one sentence on which UAE value it shows.","Choose the ONE moment your group thinks had the greatest positive impact, and justify your choice.","Design your timeline as a poster or digital presentation.","Present your timeline in a 3-minute pitch. Use Word Bank vocabulary and check all facts against reliable sources."], rubric:[["1–2","Few moments included; facts are inaccurate or unexplained."],["3–4","Some accurate moments; values are named but not explained."],["5–6","Accurate, well-chosen moments; values clearly linked; reasonable justification of the key moment."],["7–8","Accurate, insightful timeline; values thoughtfully linked; convincing, well-evidenced justification of the key moment."]]},
  game:{type:"sort", title:"Tool of International Relations", prompt:"Sort each example under the tool of international relations it best shows.", bins:["Diplomacy & mediation","Humanitarian & foreign aid","Global cooperation & partnerships"], items:[["Helping two countries agree to a prisoner exchange",0],["Sending medical supplies after an earthquake",1],["Hosting COP28 in Dubai in 2023",2],["Holding talks to reduce tensions between neighbours",0],["Funding schools and hospitals in developing countries",1],["Joining the United Nations in 1971",2],["Delivering food aid through the Emirates Red Crescent",1],["Signing trade agreements with other nations",2]]},
  quiz:[["In which year did the UAE join the United Nations?",["1971","1990","2001"],0],["What is 'diplomacy'?",["A type of army","Managing relationships between countries through discussion and negotiation","A trade tax"],1],["What does 'sovereignty' mean?",["A country's right to govern itself without outside interference","A type of foreign aid","A world map"],0],["Where was COP28 held in 2023?",["Abu Dhabi","Sharjah","Dubai"],2],["What is 'foreign aid'?",["Money a country spends on itself","A foreign holiday","Money, goods or services given by one country to help another"],2],["Which principle is part of the UAE's foreign policy?",["Solving disputes through dialogue and peaceful solutions","Avoiding all other countries","Ignoring international organisations"],0],["Which organisation delivers UAE humanitarian aid around the world?",["A football club","The Emirates Red Crescent","A shopping mall"],1],["Why can foreign aid be seen as ethical, not just practical?",["It makes a country famous","It reflects generosity and respect for human dignity","It is required by every school"],1]],
  exit:"Name ONE example of the UAE's international relations and the UAE value it reflects.",
  copy:{facts:["The UAE joined the United Nations in 1971 and follows a foreign policy based on dialogue, respect for sovereignty and peaceful solutions.","The UAE builds relationships through diplomacy, humanitarian aid, trade and global events such as COP28 (Dubai, 2023).","The UAE's international relations reflect national values of tolerance, generosity and cooperation."]},
  next:"Next lesson: we continue Unit 1 by exploring global ethical challenges such as poverty and climate change."
 },
 {
  id:"l3", lesson:3, title:"Global Ethical Challenges (1)", unit:"Unit 1: Introduction to Global Ethics", art:"nature",
  dna:"Recap: in one sentence, name one way the UAE works with other countries from last lesson. Now think: write down ONE problem in the world today that you think is unfair to people who did not cause it.",
  dnaQs:["Name one way the UAE works with other countries (from last lesson).","Name ONE world problem that you think is unfair to people who did not cause it."],
  dnaHint:"For the recap, you could mention diplomacy, humanitarian aid or hosting COP28. For the world problem, strong examples are climate change (often hitting poorer countries hardest, even though they produce fewer emissions) or poverty (children born into poverty did not choose it).",
  intentions:["Understand poverty and climate change as global ethical challenges.","Explore why these challenges raise questions of fairness and responsibility.","Evaluate who should take responsibility for responding to them."],
  criteria:["I can explain why poverty and climate change are ethical challenges, not only economic or scientific ones.","I can describe how these challenges raise questions of fairness.","I can evaluate who should take responsibility for responding to them."],
  concept:{key:"Global interactions", related:"Fairness, Sustainability", soi:"Global challenges such as poverty and climate change raise urgent questions about fairness and shared responsibility.", context:"Globalisation and Sustainability — exploring the human impact of global challenges and our responsibility to respond.", uae:"The UAE hosted COP28 in Dubai in 2023, which produced the 'UAE Consensus'; the UAE has a Net Zero by 2050 strategic initiative and invests in renewable energy such as Masdar; links to Sciences (climate) and Individuals & Societies (development)."},
  words:[["Poverty","The state of not having enough money or resources to meet basic needs."],["Inequality","An unfair difference in wealth, opportunity or treatment between people or groups."],["Climate change","Long-term change in the Earth's climate, greatly accelerated by human activity such as burning fossil fuels."],["Sustainability","Meeting the needs of today without harming the ability of future generations to meet theirs."],["Climate justice","The idea that the effects and costs of climate change should be shared fairly."],["Vulnerable","At greater risk of being harmed."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion B — Investigating", steps:["Choose EITHER poverty OR climate change.","Research ONE real example of how it affects a specific community or region, using at least two reliable sources (e.g. UN, World Bank, UNICEF, reputable news).","Record: who is affected, how they are affected, and why this is unfair.","Note one response (by a government, organisation or the UAE) that is helping to address it."], prompts:["The challenge and example I chose, and my two sources","Who is affected and how","Why this situation is unfair","One response that is helping, and who is leading it"], success:"Good examples include low-lying island nations threatened by rising sea levels, communities affected by drought and food insecurity, and children unable to attend school because of poverty. Strong answers explain the fairness issue clearly (e.g. those least responsible for emissions are often most affected) and avoid uncertain statistics unless they come from a reliable source. For the top band, use two credible sources and evaluate how effective the response is."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"A small coastal community produces very little pollution, yet it faces rising sea levels and stronger storms that damage homes and farmland. Meanwhile, much of the world's pollution has historically come from wealthier, industrialised nations.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain why this situation is an ethical challenge, not just a scientific one.","Use at least THREE words from the Word Bank (e.g. climate justice, vulnerable, inequality) accurately.","Conclude with who you think should take the most responsibility for helping, and why."], model:"This situation is an ethical challenge because it raises the question of fairness: the coastal community is vulnerable to the effects of climate change even though it has contributed very little to causing it. This reflects a wider inequality, as wealthier nations have historically produced more pollution while poorer communities often face the greatest harm. The idea of climate justice suggests that those who contributed most to the problem, and who have the most resources, should take the greatest responsibility for helping. I think wealthier nations should lead by reducing emissions and funding support for vulnerable communities, because responsibility should match both contribution and ability to help.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; conclusion on responsibility is well-justified."]], starters:["This situation is an ethical challenge because ___.","The community is vulnerable because ___.","This reflects a wider inequality, as ___.","I think ___ should take the most responsibility because ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Fair Share Summit", steps:["In groups of 3–4, each group represents a fictional country (e.g. a wealthy industrial nation, a fast-growing economy, a small island nation, a low-income farming nation).","Prepare a 2-minute statement explaining how poverty and/or climate change affect your country and what you think is a fair response.","Hold a class 'Fair Share Summit' where each country presents and responds to the others.","As a class, try to agree on a joint 'Summit Agreement' of 3 fair actions.","Reflect individually: was the final agreement fair to everyone? Use Word Bank vocabulary in your statement."], rubric:[["1–2","Statement is vague; little link to fairness or responsibility."],["3–4","Basic statement with some relevant points; limited engagement with other countries."],["5–6","Clear, realistic statement; fairness is explained; reasonable engagement with other views."],["7–8","Insightful, well-justified statement; fairness and responsibility explored in depth; strong, respectful engagement with other views."]]},
  game:{type:"sort", title:"Poverty or Climate Change?", prompt:"Sort each example: is it mainly about poverty, or mainly about climate change?", bins:["Poverty","Climate change"], items:[["A family cannot afford enough nutritious food",0],["Rising sea levels threaten coastal homes",1],["Children leave school early to work and support their family",0],["Longer and hotter heatwaves damage crops",1],["A community has no access to clean water because it cannot afford a well",0],["Glaciers melting faster than in the past",1],["Adults cannot afford basic healthcare",0],["More frequent extreme storms",1]]},
  quiz:[["What is 'poverty'?",["Not having enough money or resources to meet basic needs","Choosing to spend less","Living in a small house"],0],["What does 'sustainability' mean?",["Using as many resources as possible now","Only recycling paper","Meeting today's needs without harming future generations' ability to meet theirs"],2],["What is 'climate justice'?",["A court for weather","The idea that the effects and costs of climate change should be shared fairly","A type of renewable energy"],1],["Why is climate change an ethical challenge, not only a scientific one?",["Because it only affects animals","Because those least responsible are often the most affected","Because it is not real"],1],["What does 'vulnerable' mean?",["At greater risk of being harmed","Very strong","Wealthy"],0],["Which global climate conference was held in Dubai in 2023?",["COP28","The Olympic Games","Expo 2010"],0],["Which is an example of the UAE investing in clean energy?",["Building more coal power stations","Masdar and renewable energy projects","Banning all electricity"],1],["According to climate justice, who should take more responsibility for helping?",["Only the poorest countries","Nobody","Those who contributed most to the problem and have the most resources"],2]],
  exit:"In one sentence, explain why poverty OR climate change is a question of fairness.",
  copy:{facts:["Poverty and climate change are global ethical challenges because they raise questions of fairness and responsibility.","Climate change often affects vulnerable communities most, even when they contributed least to causing it.","The UAE hosted COP28 in Dubai in 2023 and has committed to a Net Zero by 2050 strategic initiative."]},
  next:"Next lesson: we continue Unit 1 by exploring further global ethical challenges, including refugees, global health and human trafficking."
 },
 {
  id:"l4", lesson:4, title:"Global Ethical Challenges (2)", unit:"Unit 1: Introduction to Global Ethics", art:"respect",
  dna:"Recap: in one sentence, explain what 'climate justice' means from last lesson. Now think: imagine you had to leave your home suddenly and could only take one small bag. Write down ONE thing you would take, and ONE thing you would find hardest to leave behind.",
  dnaQs:["In one sentence, what does 'climate justice' mean?","If you had to leave home suddenly with one small bag, what ONE thing would you take?","What would you find hardest to leave behind?"],
  dnaHint:"Climate justice is the idea that the effects and costs of climate change should be shared fairly. For the imagining task, there is no wrong answer — many people mention a phone, a family photo or important documents, and find it hardest to leave family, friends or a sense of home. This helps us understand, with empathy, what people who are forced to leave their homes experience.",
  intentions:["Understand refugees, global health and human trafficking as global ethical challenges.","Explore these challenges with empathy, focusing on human dignity and rights.","Evaluate how individuals, nations and organisations can respond responsibly."],
  criteria:["I can explain why refugee crises, global health and human trafficking are ethical challenges.","I can discuss these challenges respectfully and with empathy, focusing on human dignity.","I can evaluate how different groups can respond responsibly."],
  concept:{key:"Global interactions", related:"Human dignity, Rights", soi:"Protecting human dignity in times of crisis is a shared global responsibility.", context:"Fairness and Development — exploring how people's rights and dignity can be protected during global crises.", uae:"The UAE's humanitarian support for displaced people, its support for global health initiatives (such as the Reaching the Last Mile initiative against preventable diseases), and its Federal Law No. 51 of 2006 on combating human trafficking; links to Individuals & Societies and Sciences (health)."},
  words:[["Refugee","A person forced to leave their country because of war, persecution or disaster, who seeks safety elsewhere."],["Displacement","Being forced to leave one's home or region."],["Global health","The health of people worldwide, including efforts to prevent and treat diseases across borders."],["Human trafficking","The illegal and exploitative movement or control of people, often through force or deception."],["Exploitation","Unfairly using someone for one's own benefit."],["Human rights","The basic rights and freedoms that belong to every person."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion B — Investigating", steps:["Choose ONE challenge: supporting refugees, improving global health, or combating human trafficking.","Research how ONE organisation or country (can include the UAE) is responding, using at least two reliable sources (e.g. UNHCR, WHO, UNICEF, official UAE websites).","Record: what the challenge involves, and what the response does to protect human dignity.","Note one difficulty the response faces.","Keep your research focused on responses and solutions, and use respectful, non-graphic language."], prompts:["The challenge I chose and my two sources","What the challenge involves","How the response protects human dignity","One difficulty the response faces"], success:"Good examples include UNHCR providing shelter and education for refugees, WHO and partners running vaccination campaigns, UAE humanitarian support for displaced people, the Reaching the Last Mile initiative against preventable diseases, and the UAE's National Committee to Combat Human Trafficking raising awareness and supporting victims. Strong answers focus on how dignity and rights are protected, use respectful language (e.g. 'people who have been displaced' rather than labels), and name a realistic difficulty such as funding or access. For the top band, use two credible sources and evaluate the response."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"A family arrives in a new country after fleeing conflict at home. The children have missed a year of school, the parents' qualifications are not recognised, and some local people are unsure how to welcome them.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain what the host community could do to protect the family's dignity and rights.","Use at least THREE words from the Word Bank (e.g. refugee, displacement, human rights) accurately.","Conclude with why welcoming refugees is a moral responsibility, not only a political decision."], model:"The host community can protect the refugee family's dignity by meeting their basic needs while also helping them rebuild a normal life. Displacement has already taken away their home and routines, so access to school for the children is essential, as education is a basic human right. The community could also help the parents have their qualifications recognised or offer training, so that they can work and support themselves rather than depend on others. Welcoming refugees is a moral responsibility, not only a political decision, because every person has equal human dignity and nobody chooses to be forced from their home.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately; respectful tone."],["7–8","Well-structured paragraph; 3+ key terms used accurately; respectful, empathetic tone; conclusion is well-justified."]], starters:["The host community could protect the family's dignity by ___.","Displacement has already ___, so ___.","Access to ___ is important because it is a human right.","Welcoming refugees is a moral responsibility because ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Dignity in Crisis Awareness Guide", steps:["In groups of 3–4, choose ONE challenge: refugees, global health or human trafficking.","Create a short awareness guide (leaflet, poster or slides) for Year 10 students explaining the challenge in clear, respectful language.","Include: what the challenge is, why it is an ethical issue, how organisations or the UAE are responding, and 2–3 safe, realistic ways students can help (e.g. supporting reputable charities, staying informed, speaking respectfully).","For human trafficking, include a 'stay safe' tip, such as being careful about online offers from strangers and telling a trusted adult if something feels wrong.","Present your guide in a 3-minute pitch. Use Word Bank vocabulary and keep all content respectful and non-graphic."], rubric:[["1–2","Guide is vague or inaccurate; little link to human dignity."],["3–4","Basic guide; challenge described; limited explanation of the ethical issue or response."],["5–6","Clear, accurate guide; ethical issue explained; realistic ways to help; respectful tone."],["7–8","Insightful, accurate and sensitive guide; ethical issue and responses explained in depth; practical, safe and well-justified actions."]]},
  game:{type:"sort", title:"Which Global Challenge?", prompt:"Sort each response under the global challenge it helps to address.", bins:["Supporting refugees","Global health","Combating human trafficking"], items:[["Providing tents, food and schooling for displaced families",0],["Running vaccination campaigns in remote regions",1],["Raising awareness of fake job offers that trick people",2],["Helping new arrivals learn the local language",0],["Training doctors and nurses in low-income countries",1],["Passing laws to punish those who exploit people",2],["Supporting victims to recover safely and return home",2],["Fighting the spread of preventable diseases",1]]},
  quiz:[["Who is a 'refugee'?",["A tourist on holiday","A person forced to leave their country because of war, persecution or disaster, who seeks safety elsewhere","A person moving for a new job"],1],["What does 'exploitation' mean?",["Unfairly using someone for one's own benefit","Exploring a new country","Helping someone in need"],0],["What is 'global health'?",["The health of one hospital","A fitness app","The health of people worldwide, including preventing and treating diseases across borders"],2],["Why do diseases need a global response?",["Because they can spread across borders","Because they only affect one country","Because they cannot be treated"],0],["Which UN agency is focused on supporting refugees?",["UNHCR","FIFA","OPEC"],0],["Which is a safe way to protect yourself from trafficking risks online?",["Accept job offers from strangers","Share your personal details with anyone","Be careful about offers from strangers and tell a trusted adult if something feels wrong"],2],["What is the most respectful way to talk about people who have fled conflict?",["Using negative labels","Focusing on their dignity and rights as people","Blaming them for the situation"],1],["Which UAE law addresses combating human trafficking?",["Federal Law No. 51 of 2006","The UAE Traffic Law","There is no such law"],0]],
  exit:"Write ONE way a school community could help protect the dignity of people affected by a global crisis.",
  copy:{facts:["Refugee crises, global health threats and human trafficking are ethical challenges because they affect human dignity and rights.","Responses include humanitarian aid, vaccination and health programmes, laws against exploitation and awareness campaigns.","The UAE supports displaced people and global health initiatives, and combats human trafficking through Federal Law No. 51 of 2006."]},
  next:"Next lesson: we complete Unit 1 by exploring how ethical challenges can be addressed at a global level."
 },
 {
  id:"l5", lesson:5, title:"Addressing Ethical Challenges at a Global Level", unit:"Unit 1: Introduction to Global Ethics", art:"power",
  dna:"Unit 1 vocabulary check! Define each term as quickly as you can: Interdependence, Diplomacy, Sustainability, Refugee, Human rights. This is our final lesson of Unit 1 — let's see how much has stuck.",
  dnaQs:["Interdependence and Diplomacy — what does each mean?","Sustainability and Refugee — what does each mean?","Human rights — what does it mean?"],
  dnaHint:"Interdependence: a situation where people or countries rely on each other. Diplomacy: managing relationships between countries through discussion and negotiation. Sustainability: meeting today's needs without harming future generations. Refugee: a person forced to leave their country who seeks safety elsewhere. Human rights: the basic rights and freedoms that belong to every person.",
  intentions:["Understand how ethical challenges can be addressed at a global level.","Explore the roles of international organisations, governments and individuals.","Evaluate which responses are most effective and justify a personal commitment to act."],
  criteria:["I can describe how international organisations and governments address global ethical challenges.","I can explain the role individuals can play.","I can evaluate the effectiveness of a global response and justify my own commitment."],
  concept:{key:"Global interactions", related:"Cooperation, Responsibility", soi:"Global ethical challenges are best addressed through cooperation between nations, organisations and individuals.", context:"Globalisation and Sustainability — exploring how shared action can create a fairer, more sustainable world.", uae:"The UAE's commitment to the UN Sustainable Development Goals (SDGs), its humanitarian aid, its hosting of COP28 (2023), and its culture of volunteering and giving; draws together Lessons 1–4."},
  words:[["International organisation","A body made up of many countries working together, such as the United Nations."],["Sustainable Development Goals (SDGs)","17 global goals agreed by UN member states in 2015 to end poverty, protect the planet and improve lives by 2030."],["Collective action","People or groups working together to achieve a shared goal."],["Accountability","Being responsible for keeping promises and explaining one's actions."],["Advocacy","Publicly supporting or speaking up for a cause."],["Volunteering","Giving time and effort to help others without being paid."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion A — Knowing and Understanding", steps:["Choose ONE of the UN Sustainable Development Goals (SDGs) linked to a challenge from this unit (e.g. No Poverty, Climate Action, Good Health and Well-being).","Research it using at least two reliable sources (e.g. the official UN SDG website, UAE government websites).","Record: what the goal aims to achieve, and ONE example of global or UAE action toward it.","Note one action individuals or schools can take to support the goal."], prompts:["The SDG I chose and my two sources","What the goal aims to achieve","One example of global or UAE action toward it","One action individuals or schools can take"], success:"Good examples include SDG 1 (No Poverty), SDG 3 (Good Health and Well-being), SDG 4 (Quality Education) and SDG 13 (Climate Action). Strong answers accurately explain the goal's aim, give a specific example of action (e.g. a UN programme, a UAE humanitarian or clean-energy initiative), and suggest a realistic individual action. For the top band, use two credible sources and comment on how effective the action has been so far."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"Some people say: 'Global problems are far too big. Only governments and the United Nations can make a difference — what one student does will not change anything.'", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), respond to this statement, explaining whether you agree or disagree.","Use at least FOUR words from across Unit 1's Word Bank (any lesson) accurately.","Conclude with ONE realistic commitment you could make to help address a global ethical challenge."], model:"While it is true that international organisations and governments have the greatest power to address global challenges, I disagree that individuals cannot make a difference. Collective action is built from many individual choices: when thousands of people reduce waste, volunteer or engage in advocacy, they can influence the decisions of companies and governments. Global citizens also help hold leaders to accountability by staying informed and speaking up about issues such as climate change and poverty. My commitment is to reduce my single-use plastic and to volunteer with a school sustainability project, because small actions, repeated by many people, contribute to real change. (Either view can earn full marks if the reasoning is well-justified.)", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1–2 key terms used; reasoning is vague."],["5–6","Clear paragraph structure; 3 key terms used mostly accurately; reasonable argument."],["7–8","Well-structured paragraph; 4+ key terms used accurately across the unit; argument and commitment are convincing and well-justified."]], starters:["While it is true that ___, I agree / disagree that ___.","Collective action is built from ___.","Global citizens can hold leaders to accountability by ___.","My commitment is to ___ because ___."]},
  task3:{title:"Project Task (Unit Showcase)", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Global Action Plan", steps:["In groups of 3–4, choose ONE global ethical challenge studied this unit (poverty, climate change, refugees, global health or human trafficking).","Create a three-level action plan: what international organisations should do, what governments (including the UAE) should do, and what students and schools can do.","Explain which ethical principle (e.g. fairness, human dignity, shared responsibility) guides your plan.","Identify one obstacle to your plan and how it could be overcome.","Present your plan to the class in a 3-minute pitch. Use Word Bank vocabulary from across the unit."], rubric:[["1–2","Plan is vague; levels are missing or unclear; little ethical reasoning."],["3–4","Basic plan covering some levels; ethical principle named but not explained."],["5–6","Clear plan covering all three levels; ethical principle explained; obstacle identified and addressed."],["7–8","Insightful, realistic plan at all three levels; ethical reasoning is thoughtful and connected across the unit; obstacle response is convincing."]]},
  game:{type:"sort", title:"Who Can Take This Action?", prompt:"Sort each action by who is mainly responsible for carrying it out.", bins:["International organisations","Governments","Individuals & schools"], items:[["Agreeing the 17 Sustainable Development Goals",0],["Hosting a global climate conference such as COP28",1],["Reducing single-use plastic at home",2],["Coordinating emergency aid across many countries",0],["Passing laws to protect people from exploitation",1],["Volunteering with a local charity",2],["Investing in national renewable energy",1],["Running a school awareness campaign",2]]},
  quiz:[["What are the Sustainable Development Goals (SDGs)?",["17 global goals agreed by UN member states in 2015 to improve lives and protect the planet by 2030","A football tournament","The rules of one school"],0],["What is 'collective action'?",["One person working alone","People or groups working together to achieve a shared goal","A type of tax"],1],["What does 'advocacy' mean?",["Staying silent about issues","Buying more products","Publicly supporting or speaking up for a cause"],2],["Which is an example of an international organisation?",["The United Nations","A local café","A family"],0],["Which statement best describes how global challenges are addressed?",["Only individuals matter","Only governments matter","Cooperation between organisations, governments and individuals is needed"],2],["What does 'accountability' mean for leaders?",["Being responsible for keeping promises and explaining their actions","Never being questioned","Only counting money"],0],["Which is a realistic way a student can help address a global challenge?",["Doing nothing because the problem is too big","Volunteering and staying informed","Blaming other countries"],1],["How do the UAE's actions connect to the SDGs?",["They have no connection","Through humanitarian aid, clean-energy investment and hosting COP28","Only through sport"],1]],
  exit:"Write ONE realistic commitment you will make to help address a global ethical challenge.",
  copy:{facts:["Global ethical challenges are best addressed through cooperation between international organisations, governments and individuals.","The 17 UN Sustainable Development Goals (agreed in 2015) set a shared plan to end poverty, protect the planet and improve lives by 2030.","Individuals contribute through collective action, volunteering, advocacy and responsible choices."]},
  next:"Unit 1: Introduction to Global Ethics is complete! Next lesson begins Unit 2: Financial Awareness, starting with recognising the value of money."
 },
 {
  id:"l6", lesson:6, title:"Recognising the Value of Money", unit:"Unit 2: Financial Awareness", art:"business",
  dna:"Welcome to Unit 2! Think about the last thing you bought with your own money (or that someone bought for you). Write down what it was, roughly how much it cost, and whether it was a need or a want. Would you buy it again?",
  dnaQs:["What was the last thing you (or someone for you) bought?","Was it a need or a want?","Would you buy it again? Why or why not?"],
  dnaHint:"A good answer names a specific item, decides whether it was a need (something essential, like food or school supplies) or a want (something nice to have, like a game or snack), and gives a reason for buying it again or not — for example, whether it was good value or used often.",
  intentions:["Understand what money is and why it has value.","Explore the difference between needs and wants and the idea of opportunity cost.","Apply responsible decision-making to spending and saving choices."],
  criteria:["I can explain what money is and why it has value.","I can distinguish between needs and wants and explain opportunity cost.","I can make and justify a responsible spending or saving decision."],
  concept:{key:"Choices", related:"Responsibility, Value", soi:"Recognising the value of money helps individuals make responsible choices that benefit themselves, their families and their community.", context:"Personal and Cultural Expression — exploring how values and priorities shape the way we use money.", uae:"Islamic and Emirati values of moderation and avoiding waste (israf), generosity and charity (sadaqah and zakat), and the UAE's focus on financial literacy for young people; links to Mathematics (percentages and budgeting)."},
  words:[["Money","Something accepted in exchange for goods and services, such as the UAE dirham."],["Value","The worth or usefulness of something."],["Needs","Things essential for living, such as food, shelter and clothing."],["Wants","Things that are nice to have but not essential."],["Opportunity cost","What you give up when you choose one option over another."],["Budget","A plan for how to spend and save money over a period of time."]],
  task1:{title:"Research Task", mins:20, criterion:"Criterion A — Knowing and Understanding", steps:["Research the three main functions of money: a medium of exchange, a store of value and a unit of account.","Use at least two reliable sources (e.g. the Central Bank of the UAE website, financial literacy websites for young people).","Record: what each function means, with one everyday example for each.","Note one reason why money has value even though notes and coins are only paper, plastic or metal."], prompts:["My two sources","Medium of exchange — meaning and example","Store of value — meaning and example","Unit of account — meaning and example","Why money has value"], success:"Medium of exchange: money is used to buy and sell (e.g. paying AED 10 for lunch instead of swapping goods). Store of value: money can be saved and used later (e.g. saving Eid money for a future purchase). Unit of account: money lets us compare the value of different things (e.g. comparing the prices of two phones). Strong answers explain that money has value because people trust it and agree to accept it, and because it is backed by a country's central bank and economy. For the top band, use two credible sources and give clear, original examples."},
  task2:{title:"Literacy Task", mins:25, criterion:"Criterion C — Communicating", extract:"A student receives AED 500 as an Eid gift. They are deciding between buying a new pair of designer headphones that cost AED 450, or spending AED 150 on books they need for a course and saving the rest for a laptop they will need next year.", steps:["In a structured paragraph (topic sentence, explanation, example, conclusion), explain which choice shows the student recognises the value of money.","Use at least THREE words from the Word Bank (e.g. needs, wants, opportunity cost, budget) accurately.","Conclude with your recommendation and why."], model:"The second choice shows that the student recognises the value of money, because it puts needs before wants and plans ahead. Buying the headphones would satisfy a want, but the opportunity cost would be high: the student would have little left for the books they need now or for the laptop next year. By creating a simple budget — spending on what is essential and saving the rest — the student makes the money work for both present and future needs. I recommend the second choice, because careful spending and saving reflect responsibility and moderation, though the student could also set aside a small amount for something they enjoy.", rubric:[["1–2","Limited structure; little/no key vocabulary used."],["3–4","Basic paragraph structure; 1 key term used, possibly inaccurately."],["5–6","Clear paragraph structure; 2–3 key terms used mostly accurately."],["7–8","Well-structured paragraph; 3+ key terms used accurately; recommendation is balanced and well-justified."]], starters:["The ___ choice shows the student recognises the value of money because ___.","Buying the headphones would satisfy a want, but the opportunity cost ___.","A simple budget would help by ___.","I recommend ___ because ___."]},
  task3:{title:"Project Task", mins:"2 lessons", criterion:"Criterion D — Thinking Critically", name:"Smart Spending Challenge", steps:["In groups of 3–4, you are given a fictional monthly allowance of AED 400 for a Year 10 student.","Create a simple budget dividing the money into needs, wants, saving and giving (e.g. charity or sadaqah).","Explain the opportunity cost of at least TWO of your choices.","Identify one unexpected expense that could happen (e.g. a broken charger) and show how your budget would cope.","Present your budget in a 3-minute pitch, explaining how it reflects the values of responsibility and moderation. Use Word Bank vocabulary in your presentation."], rubric:[["1–2","Budget is incomplete or unrealistic; little explanation."],["3–4","Basic budget; needs and wants identified; opportunity cost named but not explained."],["5–6","Clear, realistic budget; opportunity cost explained; unexpected expense addressed."],["7–8","Well-balanced, realistic budget; opportunity costs and values thoughtfully explained; convincing plan for unexpected expenses."]]},
  game:{type:"sort", title:"Need or Want?", prompt:"Sort each item: is it a need or a want for a Year 10 student?", bins:["Need","Want"], items:[["Healthy meals",0],["School uniform",0],["A limited-edition pair of trainers",1],["Textbooks for your course",0],["A new phone when your current one works perfectly",1],["Transport to school",0],["In-game purchases",1],["Designer sunglasses",1]]},
  quiz:[["What is 'money'?",["Something accepted in exchange for goods and services","Only gold bars","A type of bank"],0],["What is 'opportunity cost'?",["The price written on a label","What you give up when you choose one option over another","Money you find by chance"],1],["Which of these is a need?",["The latest games console","Designer sunglasses","Healthy food"],2],["What is a 'budget'?",["A plan for how to spend and save money","A type of shop","A bank card"],0],["Saving Eid money to buy something later shows money acting as a…",["Unit of account","Store of value","Medium of exchange"],1],["Why do notes and coins have value?",["Because they are made of expensive materials","Because they are colourful","Because people trust them and agree to accept them"],2],["In the extract, what is the opportunity cost of buying the headphones?",["Having little left for the books and the laptop","Nothing at all","Getting free books"],0],["Which value does avoiding waste (israf) reflect?",["Spending as much as possible","Moderation and responsibility","Competing with friends"],1]],
  exit:"Write ONE thing you will think about before you next spend your own money.",
  copy:{facts:["Money is accepted in exchange for goods and services; it works as a medium of exchange, a store of value and a unit of account.","Recognising the value of money means putting needs before wants and considering opportunity cost.","Islamic and Emirati values encourage moderation, avoiding waste (israf) and generosity through charity."]},
  next:"Next lesson: we continue Unit 2: Financial Awareness by exploring how to manage money responsibly."
 }
];
